const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('latin1');

// Search for Emily Carter near 60611
let idx = 0;
while ((idx = text.indexOf('Emily Carter', idx)) !== -1) {
  const context = text.substring(Math.max(0,idx-300), idx+500).replace(/[^\x20-\x7E]/g, ' ');
  if (context.includes('60611')) {
    console.log('MATCH - Emily Carter with zip 60611:');
    console.log(context);
  }
  idx += 12;
}
console.log('---');

// Also check: what zip codes are associated with Emily Carter user records
idx = 0;
while ((idx = text.indexOf('Emily Carter', idx)) !== -1) {
  const context = text.substring(Math.max(0,idx-100), idx+600).replace(/[^\x20-\x7E]/g, ' ');
  if (context.includes('address1')) {
    console.log('Emily Carter address record:');
    // Extract zip
    const zipMatch = context.match(/\"zip\":\"(\d+)\"/);
    if (zipMatch) console.log('  Zip found: ' + zipMatch[1]);
    const userMatch = context.match(/(user_[a-f0-9]+)/);
    if (userMatch) console.log('  User ID: ' + userMatch[1]);
    console.log(context.substring(0, 400));
    console.log('');
  }
  idx += 12;
}
